$ErrorActionPreference = "Stop"

$projectRoot = (Get-Location).Path
if (-not (Test-Path (Join-Path $projectRoot "package.json"))) {
    Write-Host "ERREUR: lance ce script depuis le dossier du projet (celui avec package.json)." -ForegroundColor Red
    exit 1
}

$destination = Join-Path $projectRoot "src\routes\trophees.tsx"
$directory = Split-Path $destination -Parent

if (-not (Test-Path $directory)) {
    New-Item -ItemType Directory -Path $directory -Force | Out-Null
}

if (Test-Path $destination) {
    $backup = "$destination.backup-$(Get-Date -Format yyyyMMdd-HHmmss)"
    Copy-Item $destination $backup -Force
    Write-Host "Sauvegarde: $backup" -ForegroundColor DarkGray
}

$base64 = ""

$raw = [Convert]::FromBase64String($base64)
$inStream = New-Object System.IO.MemoryStream(, $raw)
$gzip = New-Object System.IO.Compression.GZipStream($inStream, [System.IO.Compression.CompressionMode]::Decompress)
$outStream = New-Object System.IO.MemoryStream
$gzip.CopyTo($outStream)
$gzip.Dispose()
$inStream.Dispose()

$content = [System.Text.Encoding]::UTF8.GetString($outStream.ToArray())
$outStream.Dispose()

$utf8 = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($destination, $content, $utf8)

$check = Get-Content $destination -Raw -Encoding UTF8

if (
    $check -notmatch 'createFileRoute\("/trophees"\)' -or
    $check -notmatch 'function TropheesPage' -or
    $check -notmatch 'fetchUserTrophies'
) {
    Write-Host "ERREUR: verification echouee." -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "TROPHEES RESTAUREE AVEC SUCCES" -ForegroundColor Green
Write-Host "Fichier: $destination" -ForegroundColor Cyan
Write-Host "Route: /trophees" -ForegroundColor Cyan
Write-Host ""
Write-Host "AppShell et les autres pages n'ont pas ete modifies." -ForegroundColor Green
Write-Host ""
Write-Host "Lance: npm run dev" -ForegroundColor Yellow
